'use client';
const providerKey=process.env.NEXT_PUBLIC_MODEL_KEY;
export default function Home(){return <main><h1>Chat demo</h1><button onClick={()=>fetch('/api/chat',{method:'POST',headers:{'Content-Type':'application/json','Authorization':'Bearer fixture-alice','X-Model-Key':providerKey},body:JSON.stringify({message:'Hello'})})}>Send demo message</button></main>}

const users=new Map([['Bearer fixture-alice','alice'],['Bearer fixture-bob','bob']]);
export async function POST(request){
  const user=users.get(request.headers.get('authorization'));
  if(!user)return Response.json({error:'Sign in required'},{status:401});
  const payload=await request.json();
  return Response.json({answer:`Mock reply for ${user}`,received:typeof payload.message==='string'});
}

export default {poweredByHeader:false};

import {spawnSync} from 'node:child_process';
// A noncredential canary for this local demo; never contact a model provider.
const env={...process.env,NEXT_TELEMETRY_DISABLED:'1',NEXT_PUBLIC_MODEL_KEY:'[SYNTHETIC_CANARY_REDACTED]'};
const result=spawnSync(process.execPath,['node_modules/next/dist/bin/next','build','--webpack'],{env,stdio:'inherit'});
process.exit(result.status??1);
